# Where Gaply's p_consistency departs from statcheck on purpose (Phase 1, Step 5).
#
# Run with the R that has statcheck installed, by its full path:
#
#   /usr/local/bin/Rscript make_statcheck_diff_fixtures.R
#
# Writes statcheck_diff_fixtures.csv next to this script: one invented sentence
# per departure, and what statcheck returns for it. The statcheck columns are
# read from the result object, not assumed: they are whatever names(result)
# holds in the installed version. A sentence statcheck extracts nothing from is
# written once with n_results = 0 and NA in every statcheck column.
#
# Gaply's verdict for each sentence is asserted by the Rust test
# tests/l0_statcheck_departures.rs, which reads this file.

suppressPackageStartupMessages(library(statcheck))

args <- commandArgs(trailingOnly = FALSE)
script <- sub("^--file=", "", args[grep("^--file=", args)])
out <- file.path(dirname(normalizePath(script)), "statcheck_diff_fixtures.csv")

departures <- data.frame(
  departure = c(
    "p_printed_as_zero",
    "adjusted_p_with_correction_named",
    "one_tailed_unstated",
    "alpha_other_than_05",
    "effect_size_between_statistic_and_p",
    "p_floor_printed_as_equality",
    "f_two_tailed_variance_ratio"
  ),
  sentence = c(
    "The groups differed, t(28) = 4.20, p = .000.",
    "After Bonferroni correction the groups differed, t(28) = 2.10, p = .27.",
    "The groups differed, t(28) = 2.10, p = .023.",
    "Significance was set at p < .01. The groups differed, t(28) = 1.90, p = .02.",
    "The groups differed, t(28) = 2.10, d = 0.40, p = .045.",
    "Old participants were slower, F(1, 62) = 78.22, p = 0.0001.",
    "The variance ratios differed, F(10, 10) = 6.40, p = .01."
  ),
  stringsAsFactors = FALSE
)

# statcheck's own defaults, named so the header records them.
call_args <- list(stat = c("t", "F", "cor", "chisq", "Z"), OneTailedTests = FALSE,
                  alpha = .05, pEqualAlphaSig = TRUE, pZeroError = TRUE,
                  OneTailedTxt = FALSE, AllPValues = FALSE, messages = FALSE)

results <- lapply(departures$sentence, function(s) {
  r <- do.call(statcheck, c(list(texts = s), call_args))
  if (is.null(r)) data.frame() else as.data.frame(r, stringsAsFactors = FALSE)
})

cols <- unique(unlist(lapply(results, names)))
if (length(cols) == 0) stop("statcheck returned no result for any sentence: no column names to record")

rows <- list()
for (i in seq_len(nrow(departures))) {
  r <- results[[i]]
  n <- nrow(r)
  if (n == 0) {
    vals <- as.list(rep(NA, length(cols)))
    names(vals) <- cols
    rows[[length(rows) + 1]] <- data.frame(departures[i, ], n_results = 0, vals,
                                           check.names = FALSE, stringsAsFactors = FALSE)
  } else {
    for (j in seq_len(n)) {
      vals <- lapply(cols, function(c) if (c %in% names(r)) r[[c]][j] else NA)
      names(vals) <- cols
      rows[[length(rows) + 1]] <- data.frame(departures[i, ], n_results = n, vals,
                                             check.names = FALSE, stringsAsFactors = FALSE)
    }
  }
}
d <- do.call(rbind, rows)

arg_text <- paste(names(call_args), sapply(call_args, function(v) paste(v, collapse = "|")),
                  sep = "=", collapse = "; ")
con <- file(out, "w")
writeLines(c(
  "# What statcheck returns for one invented sentence per Gaply departure.",
  "# Generated by /usr/local/bin/Rscript make_statcheck_diff_fixtures.R (do not edit by hand).",
  paste0("# ", R.version.string),
  paste0("# statcheck ", as.character(packageVersion("statcheck"))),
  paste0("# statcheck arguments: ", arg_text)
), con)
close(con)
suppressWarnings(write.table(d, out, sep = ",", quote = TRUE, row.names = FALSE,
                             na = "NA", append = TRUE, qmethod = "double"))

cat("wrote", out, "\n")
print(d[, setdiff(names(d), c("sentence", "source", "raw"))], row.names = FALSE)
